from z3 import *

START_LOC = "Fisherman's Wharf"
START_TIME = 9 * 60

travel_times = {
    ("Fisherman's Wharf", "Golden Gate Park"): 25,
    ("Fisherman's Wharf", "Presidio"): 17,
    ("Fisherman's Wharf", "Richmond District"): 18,
    ("Golden Gate Park", "Fisherman's Wharf"): 24,
    ("Golden Gate Park", "Presidio"): 11,
    ("Golden Gate Park", "Richmond District"): 7,
    ("Presidio", "Fisherman's Wharf"): 19,
    ("Presidio", "Golden Gate Park"): 12,
    ("Presidio", "Richmond District"): 7,
    ("Richmond District", "Fisherman's Wharf"): 18,
    ("Richmond District", "Golden Gate Park"): 9,
    ("Richmond District", "Presidio"): 7,
}


def travel(a, b):
    return travel_times[(a, b)]


def fmt(minutes):
    minutes = minutes % 1440
    period = "AM" if minutes < 720 else "PM"
    hour = (minutes // 60) % 12
    if hour == 0:
        hour = 12
    return f"{hour}:{minutes % 60:02d}{period}"


friends = {
    "Melissa": {"loc": "Golden Gate Park", "start": 8 * 60 + 30, "end": 20 * 60, "min": 15},
    "Emily": {"loc": "Richmond District", "start": 16 * 60 + 45, "end": 22 * 60, "min": 120},
    "Nancy": {"loc": "Presidio", "start": 19 * 60 + 45, "end": 22 * 60, "min": 105},
}
names = ["Melissa", "Emily", "Nancy"]

met = {name: Bool(name) for name in names}
pos = {name: Int(name) for name in names}
start = {name: Int(name) for name in names}
end = {name: Int(name) for name in names}
wait = {name: Int(name) for name in names}

opt = Optimize()

for name in names:
    info = friends[name]
    opt.add(pos[name] >= 0, pos[name] <= 2)
    opt.add(start[name] >= 0, start[name] <= 1440)
    opt.add(end[name] >= 0, end[name] <= 1440)
    opt.add(wait[name] >= 0)
    opt.add(Implies(Not(met[name]), wait[name] == 0))
    opt.add(
        Implies(
            met[name],
            And(
                start[name] >= info["start"],
                end[name] <= info["end"],
                end[name] == start[name] + info["min"],
            )
        )
    )

for i in names:
    for j in names:
        if i != j:
            opt.add(Implies(And(met[i], met[j]), pos[i] != pos[j]))

for name in names:
    preds = [And(met[j], pos[j] == pos[name] - 1) for j in names if j != name]
    opt.add(Implies(And(met[name], pos[name] > 0), Or(*preds)))

for name in names:
    loc = friends[name]["loc"]
    arrive0 = START_TIME + travel(START_LOC, loc)
    opt.add(
        Implies(
            And(met[name], pos[name] == 0),
            And(start[name] >= arrive0, wait[name] == start[name] - arrive0),
        )
    )

    for j in names:
        if j == name:
            continue
        loc_j = friends[j]["loc"]
        arrive = end[j] + travel(loc_j, loc)

        opt.add(
            Implies(
                And(met[name], met[j], pos[name] == 1, pos[j] == 0),
                And(start[name] >= arrive, wait[name] == start[name] - arrive),
            )
        )
        opt.add(
            Implies(
                And(met[name], met[j], pos[name] == 2, pos[j] == 1),
                And(start[name] >= arrive, wait[name] == start[name] - arrive),
            )
        )

count = If(met[names[0]], 1, 0)
total_wait = If(met[names[0]], wait[names[0]], 0)
sum_start = If(met[names[0]], start[names[0]], 0)

for name in names[1:]:
    count = count + If(met[name], 1, 0)
    total_wait = total_wait + If(met[name], wait[name], 0)
    sum_start = sum_start + If(met[name], start[name], 0)

opt.maximize(count)
opt.minimize(total_wait)
opt.minimize(sum_start)

res = opt.check()
if res != sat:
    print([])
else:
    model = opt.model()

    def int_val(expr):
        return model.evaluate(expr, model_completion=True).as_long()

    def bool_val(expr):
        return model.evaluate(expr, model_completion=True).is_true()

    ordered = [name for name in names if bool_val(met[name])]
    ordered.sort(key=lambda name: int_val(pos[name]))

    itinerary = [f"You start at {START_LOC} at {fmt(START_TIME)}."]
    prev_loc = START_LOC
    prev_end = START_TIME

    for name in ordered:
        loc = friends[name]["loc"]
        t = travel(prev_loc, loc)
        arrive = prev_end + t

        itinerary.append(f"You travel to {loc} in {t} minutes and arrive at {fmt(arrive)}.")

        s = int_val(start[name])
        if s > arrive:
            itinerary.append(f"You wait until {fmt(s)}.")

        e = int_val(end[name])
        d = e - s
        itinerary.append(f"You meet {name} for {d} minutes from {fmt(s)} to {fmt(e)}.")

        prev_loc = loc
        prev_end = e

    print(itinerary)

from z3 import *


def to_minutes(h, m, period):
    if period == "AM":
        if h == 12:
            h = 0
    else:
        if h != 12:
            h += 12
    return h * 60 + m


def format_time(t):
    t = int(t)
    hour = (t // 60) % 24
    minute = t % 60
    suffix = "AM" if hour < 12 else "PM"
    h12 = hour % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{minute:02d}{suffix}"


